import{_ as o,r as s,o as r,c as l,e as t,a as d,s as c}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Поле Record Finder - October CMS - 3.x","titleTemplate":false,"description":"Виджет формы","frontmatter":{"subtitle":"Виджет формы","shortname":"Record Finder"},"headers":[{"level":2,"title":"Использование в Tailor","slug":"использование-в-tailor","link":"#использование-в-tailor","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/element/form/widget-recordfinder.md","filePath":"3.x/ru/element/form/widget-recordfinder.md"}'),p={name:"3.x/ru/element/form/widget-recordfinder.md"};function u(i,e,k,g,m,y){const a=s("pre-heading"),n=s("post-heading");return r(),l("div",null,[t(a),e[0]||(e[0]=d("h1",null,"Поле Record Finder",-1)),t(n),e[1]||(e[1]=c(`<p><code>recordfinder</code> — рендерит поле с деталями связанной записи. При раскрытии поля отображается всплывающий список для поиска среди большого количества записей. Поддерживается только единичными отношениями.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">list</span><span class="token punctuation">:</span> ~/plugins/rainlab/user/models/user/columns.yaml
</code></pre></div><p>Поддерживаются и обычно используются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении поля формы пользователю.</td></tr><tr><td><strong>default</strong></td><td>значение по умолчанию (строка), необязательно.</td></tr><tr><td><strong>comment</strong></td><td>пояснительный комментарий под полем.</td></tr><tr><td><strong>keyFrom</strong></td><td>имя столбца в отношении, используемого для ключа. По умолчанию: <code>id</code>.</td></tr><tr><td><strong>nameFrom</strong></td><td>имя столбца в отношении, используемого для отображения имени. По умолчанию: <code>name</code>.</td></tr><tr><td><strong>descriptionFrom</strong></td><td>имя столбца в отношении, используемого для отображения описания. По умолчанию: <code>description</code>.</td></tr><tr><td><strong>title</strong></td><td>текст для отображения в заголовке всплывающего окна.</td></tr><tr><td><strong>list</strong></td><td>массив конфигурации или ссылка на файл определения столбцов списка.</td></tr><tr><td><strong>filter</strong></td><td>ссылка на файл определения областей фильтрации, см. <a href="./../../extend/lists/filters.html">фильтры списков</a>.</td></tr><tr><td><strong>showSetup</strong></td><td>отображает кнопку настройки для конфигурации столбцов списка и количества записей на странице. По умолчанию: <code>false</code></td></tr><tr><td><strong>structure</strong></td><td>включает структурированный список только для чтения для выбора записей, см. <a href="./../../extend/lists/structures.html">статью о сортировке записей</a>. Установите <code>false</code> для отключения, иначе включается, когда модель использует древовидный интерфейс.</td></tr><tr><td><strong>defaultSort</strong></td><td>устанавливает столбец сортировки и направление по умолчанию, когда предпочтения пользователя не определены. Поддерживает строку или массив с ключами <code>column</code> и <code>direction</code>. Направление может быть <code>asc</code> для возрастающего (по умолчанию) или <code>desc</code> для убывающего порядка.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>количество записей на странице, используйте 0 для отключения пагинации. По умолчанию: <code>10</code></td></tr><tr><td><strong>conditions</strong></td><td>задаёт необработанное условие where для применения к запросу модели списка.</td></tr><tr><td><strong>modelScope</strong></td><td>применяет метод <a href="./../../extend/database/model.html">области запроса модели</a> к <strong>связанной модели формы</strong>, может быть именем метода модели или статическим методом PHP-класса (<code>Class::method</code>). Первый аргумент будет содержать модель, к которой виджет будет прикреплять своё значение, т.е. родительскую модель.</td></tr><tr><td><strong>searchMode</strong></td><td>определяет стратегию поиска: все слова, любое слово или точная фраза. Поддерживаемые варианты: all, any, exact. По умолчанию: <code>all</code>.</td></tr><tr><td><strong>searchScope</strong></td><td>задаёт метод <a href="./../../extend/database/model.html">области запроса модели</a>, определённый в <strong>связанной модели формы</strong>, для применения к поисковому запросу, первый аргумент будет содержать поисковый термин.</td></tr><tr><td><strong>useRelation</strong></td><td>флаг для использования имени поля как имени отношения для прямого взаимодействия с родительской моделью. По умолчанию: <code>true</code>. Отключите для возврата только ID выбранной модели.</td></tr><tr><td><strong>modelClass</strong></td><td>класс модели для списка записей, когда <code>useRelation</code> установлен в <code>false</code>.</td></tr><tr><td><strong>popupSize</strong></td><td>изменяет размер всплывающего окна поиска: <code>giant</code>, <code>huge</code>, <code>large</code>, <code>small</code>, <code>tiny</code> или <code>adaptive</code>. По умолчанию: <code>huge</code></td></tr><tr><td><strong>inlineOptions</strong></td><td>отображает поле с кнопками рядом с выбранной записью, отключите этот режим при ограниченном горизонтальном пространстве. По умолчанию: <code>true</code>.</td></tr></tbody></table></div><p>Вы можете ограничить количество записей на странице с помощью свойства <code>recordsPerPage</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div><p>Используйте свойство <code>title</code> для изменения заголовка формы управления.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Find A User
</code></pre></div><p>При выборе записи атрибуты отображения могут быть выбраны из атрибутов модели с помощью свойств <code>nameFrom</code> и <code>descriptionFrom</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> name
    <span class="token key atrule">descriptionFrom</span><span class="token punctuation">:</span> email
</code></pre></div><p>Если обнаружена <a href="./../../extend/lists/structures.html">структура модели</a>, список будет отображаться как структура. Это можно явно отключить или включить с помощью свойства <strong>structure</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">structure</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><h2 id="использование-в-tailor"><a href="#использование-в-tailor" class="header-anchor">#</a> Использование в Tailor</h2><p>Когда поле <code>recordfinder</code> используется как <a href="./../../cms/tailor/content-fields.html">контентное поле в Tailor</a>, необходимо указать свойство <code>modelClass</code> для определения и нахождения отношения модели.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Product
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/october/test/models/product/columns.yaml
</code></pre></div><p>Когда <code>maxItems</code> установлен в <strong>1</strong>, отношение определяется как <code>belongsTo</code>. В противном случае отношение определяется как <code>belongsToMany</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Tag
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p>Свойство <code>inverse</code> может быть установлено в имя отношения на связанной модели. Это изменит определение отношения на <code>hasOne</code>, <code>hasMany</code> или <code>belongsToMany</code> в зависимости от настройки <code>maxItems</code> и типа отношения связанной модели.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tags</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Tags
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Tag
    <span class="token key atrule">inverse</span><span class="token punctuation">:</span> tags
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../cms/tailor/models.html">Модели Tailor</a></li><li><a href="./../../extend/database/relations.html">Отношения базы данных</a></li></ul></div>`,21))])}const b=o(p,[["render",u]]);export{f as __pageData,b as default};
